import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.DCVnL8g5.js";const u=JSON.parse('{"title":"Despliegue","description":"","frontmatter":{},"headers":[],"relativePath":"ia/huggingface/07-despliegue.md","filePath":"ia/huggingface/07-despliegue.md","lastUpdated":1789040978000,"isDraft":false}'),t={name:"ia/huggingface/07-despliegue.md"};function o(r,e,d,l,p,c){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="despliegue" tabindex="-1">Despliegue <a class="header-anchor" href="#despliegue" aria-label="Permalink to &quot;Despliegue&quot;">​</a></h1><p>Correr <code>pipeline</code> en tu portátil <strong>no es desplegar</strong>. Desplegar es exponer inferencia a otros procesos o usuarios con un contrato (API, cola, lote), límites y un dueño de la GPU o de la factura.</p><p>El capítulo 2 cubre inferencia local. vLLM, en este mismo área, cubre un <strong>servidor propio</strong>. Aquí: qué ofrece Hugging Face hoy y cuándo no usarlo.</p><p>Nombres vigentes (comprueba siempre la doc: esta capa cambia):</p><table tabindex="0"><thead><tr><th>Opción</th><th>Qué es</th></tr></thead><tbody><tr><td><strong>Local / job</strong></td><td><code>pipeline</code>, <code>generate</code>, notebook. Cero servicio.</td></tr><tr><td><strong>Servicio propio</strong></td><td>Tú pones GPU + motor (<code>vllm serve</code>, TGI, contenedor).</td></tr><tr><td><strong>Inference Providers</strong></td><td>API <em>serverless</em> enrutada por Hugging Face hacia proveedores. Pagas uso, no una máquina tuya.</td></tr><tr><td><strong>Inference Endpoints</strong></td><td>Servicio <strong>gestionado y dedicado</strong>: eliges modelo + motor (vLLM, TGI, SGLang, …) y HF aprovisiona el contenedor.</td></tr><tr><td><strong>Contenedor propio</strong></td><td>Imagen (p. ej. <code>vllm/vllm-openai</code>) en tu Kubernetes/VM. HF solo aporta los pesos.</td></tr></tbody></table><p>Documentación oficial: <a href="https://huggingface.co/docs/inference-providers/en/index" target="_blank" rel="noreferrer">Inference Providers</a>, <a href="https://huggingface.co/docs/inference-endpoints/en/index" target="_blank" rel="noreferrer">Inference Endpoints</a>, <a href="https://docs.vllm.ai/en/latest/cli/serve/" target="_blank" rel="noreferrer">vLLM serve</a>.</p><h2 id="inference-providers-api-no-tu-gpu" tabindex="-1">Inference Providers (API, no tu GPU) <a class="header-anchor" href="#inference-providers-api-no-tu-gpu" aria-label="Permalink to &quot;Inference Providers (API, no tu GPU)&quot;">​</a></h2><p>Una petición HTTP (o el SDK) va a <code>https://router.huggingface.co</code>. Hugging Face elige un proveedor según política (<code>:fastest</code>, <code>:cheapest</code>, <code>:preferred</code> o un proveedor concreto). El token necesita permiso de <strong>Inference Providers</strong> (token <em>fine-grained</em>).</p><p>Compatible con el cliente OpenAI cambiando la base:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> openai </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OpenAI</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OpenAI(</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    base_url</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://router.huggingface.co/v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    api_key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.environ[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HF_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.chat.completions.create(</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Id *servido* por algún proveedor (ficha del Hub → Inference Providers).</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # El Qwen local de los capítulos 2–4 no tiene por qué estar en esta red.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;openai/gpt-oss-120b:fastest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    messages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Di hola en una frase.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(resp.choices[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].message.content)</span></span></code></pre></div><p><code>InferenceClient</code> de <code>huggingface_hub</code> es la vía nativa (<code>client.chat.completions.create(...)</code>). El widget del Hub usa la misma red: no implica que <em>tu</em> modelo privado esté servido gratis.</p><p>Límites reales: el modelo tiene que estar <strong>ofrecido por algún proveedor</strong>; un fine-tune privado del capítulo 4 <strong>no</strong> aparece aquí hasta que alguien lo aloje. Datos de la petición salen de tu VPC hacia un tercero. Hay cold start y cuotas. No es un SLA de “esta GPU es mía”.</p><h2 id="inference-endpoints-dedicado" tabindex="-1">Inference Endpoints (dedicado) <a class="header-anchor" href="#inference-endpoints-dedicado" aria-label="Permalink to &quot;Inference Endpoints (dedicado)&quot;">​</a></h2><p><a href="https://huggingface.co/docs/inference-endpoints/en/index" target="_blank" rel="noreferrer">Endpoints</a> levanta un contenedor con el motor que elijas y el snapshot del Hub. Escalas (incluso a cero, con el coste de despertar). Sirve para <strong>tu</strong> repo, incluido privado, con la cuenta de HF pagando la instancia.</p><p>No lo confundas con Providers: Endpoints es <em>tu</em> despliegue gestionado; Providers es un catálogo multi-proveedor. El CLI <code>hf</code> incluye <code>hf endpoints</code> para operar Endpoints.</p><h2 id="contenedor-y-api-propia" tabindex="-1">Contenedor y API propia <a class="header-anchor" href="#contenedor-y-api-propia" aria-label="Permalink to &quot;Contenedor y API propia&quot;">​</a></h2><p>Si ya operas GPU, el camino directo es la imagen o el binario del motor (manual de <a href="./../vllm/05-despliegue">vLLM, despliegue</a>). Hugging Face no tiene que estar en el camino crítico: <code>from_pretrained</code> o un volumen con el snapshot bastan.</p><p>Spaces es útil para <strong>demos</strong> (Gradio/Streamlit). No lo trates como API de producción de un LLM con concurrencia: ni el aislamiento ni el hardware son los de un endpoint o un <code>vllm serve</code>.</p><h2 id="criterios-elige-con-numeros-no-con-marketing" tabindex="-1">Criterios (elige con números, no con marketing) <a class="header-anchor" href="#criterios-elige-con-numeros-no-con-marketing" aria-label="Permalink to &quot;Criterios (elige con números, no con marketing)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterio</th><th>Providers</th><th>Endpoints</th><th>Tuyo (vLLM / contenedor)</th></tr></thead><tbody><tr><td><strong>Coste</strong></td><td>Por token / petición (tarifa del proveedor).</td><td>Por minuto de instancia (aunque esté ociosa, salvo scale-to-zero).</td><td>GPU + electricidad/cloud tuya.</td></tr><tr><td><strong>Latencia</strong></td><td>Red + cola del proveedor; variable.</td><td>Dedicada; cold start si escala a 0.</td><td>La de tu red y tu batch.</td></tr><tr><td><strong>GPU</strong></td><td>No la eliges (salvo política/proveedor).</td><td>Eliges tipo de instancia.</td><td>Eliges tú.</td></tr><tr><td><strong>Privacidad</strong></td><td>El prompt sale a un proveedor.</td><td>Cuenta HF / región del producto.</td><td>Tu VPC.</td></tr><tr><td><strong>Escalado</strong></td><td>Ellos.</td><td>Autoscaling del producto.</td><td>Replica pods, <code>-tp</code>, colas.</td></tr><tr><td><strong>Cold start</strong></td><td>Posible según proveedor.</td><td>Típico al despertar de cero.</td><td>Arranque del proceso (carga de pesos).</td></tr><tr><td><strong>Modelo privado</strong></td><td>En general no, salvo que un proveedor lo sirva.</td><td>Sí, desde tu repo.</td><td>Sí, snapshot local o Hub con token.</td></tr></tbody></table><p>Ninguna columna es “la oficial”. Un prototipo de chat cabe en Providers. Un fine-tune interno con PII, en tu red. Un SaaS con SLO, Endpoints o tu cluster — mides TTFT y euros.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Llamar “despliegue” a un Colab con <code>pipeline</code>.</li><li>Apuntar producción a un id de Providers sin comprobar que el modelo <strong>está</strong> servido y con qué licencia.</li><li>Exponer un <code>vllm serve</code> en <code>:8000</code> a Internet (véase <a href="./../vllm/07-buenas-practicas">buenas prácticas de vLLM</a>).</li><li>Meter un token <code>hf_</code> en el frontend.</li><li>Usar nombres viejos de productos (“Inference API” a secas) sin mirar si hoy es Providers o Endpoints.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Un <code>base_url</code> por entorno; el cliente OpenAI ya lo usas en vLLM: cambia host, no el código.</li><li>Pin de modelo + revisión donde el producto lo permita.</li><li>Presupuesto y timeout explícitos; la GPU ajena también se dispara.</li><li>Para servir <em>tu</em> Qwen fine-tuneado, asume Endpoints o vLLM, no el router público.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Lista qué modelos de un id que uses aparecen en Providers (<code>hf models ls --warm</code> o la ficha del Hub).</li><li>Escribe en una tabla de tres filas tu caso: prototipo, datos internos, producción. Asigna una columna.</li><li>Si tienes GPU, arranca el servidor del manual vLLM y compara latencia con una llamada al router (mismo prompt, distinto backend).</li></ol>`,27)])])}const g=a(t,[["render",o]]);export{u as __pageData,g as default};
